import{_ as t,o,c as s,ag as n}from"./chunks/framework.BSwSpTvy.js";const u=JSON.parse('{"title":"📉 Auto Context Compression","description":"","frontmatter":{},"headers":[],"relativePath":"features/context-compression.md","filePath":"features/context-compression.md"}'),r={name:"features/context-compression.md"};function a(i,e,c,h,l,m){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="📉-auto-context-compression" tabindex="-1">📉 Auto Context Compression <a class="header-anchor" href="#📉-auto-context-compression" aria-label="Permalink to &quot;📉 Auto Context Compression&quot;">​</a></h1><p>When you work on long-running tasks or massive refactoring sessions, your conversation logs and tool results can rapidly bloat the LLM&#39;s context window. Hitting a 200k token limit can cause the model to crash, drop messages, or cost an enormous amount of API credits on every turn.</p><p>To prevent this, <strong>Zed Custom</strong> implements a built-in <strong>Auto Context Compression</strong> mechanism directly into the thread logic.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>When the thread exceeds <strong>70,000 words</strong> (including code mentions), <strong>Zed Custom</strong> automatically condenses the context in the background.</p><h3 id="the-workflow" tabindex="-1">The Workflow: <a class="header-anchor" href="#the-workflow" aria-label="Permalink to &quot;The Workflow:&quot;">​</a></h3><ol><li><strong>Preserve Context</strong>: We keep only the <strong>last 2 messages</strong> to maximize space recovery while maintaining immediate continuity.</li><li><strong>Consolidated Summary</strong>: The old summary is merged with new messages to create a <strong>single, dense technical snapshot</strong> of the task.</li><li><strong>Recursive State</strong>: The new summary replaces the old, ensuring you never hit context length limits even in massive refactoring sessions.</li></ol><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why this matters&quot;">​</a></h2><p>Instead of losing your place in a massive refactoring task or being forced to start a new chat, <strong>Zed Custom</strong> condenses the historical timeline into a set of dense facts. The model never forgets <em>what</em> you were doing or <em>why</em>, but it successfully clears the context window for your next turn.</p><p>This ensures you can keep coding indefinitely in the exact same thread without ever hitting &quot;Context Length Exceeded&quot; errors or suffering from extreme slow-downs.</p>',10)])])}const g=t(r,[["render",a]]);export{u as __pageData,g as default};
